mapper.update:
UPDATE t_i18n_application
SET application_name = #{next.applicationName}, default_locale = #{next.defaultLocale},
    required_locales = #{next.requiredLocalesJson},
    coverage_threshold_percent = #{next.coverageThresholdPercent}, version = version + 1,
    updated_by = #{next.updatedBy}, update_time = #{next.updateTime}
WHERE application_id = #{row.applicationId} AND version = #{row.version}

UPDATE t_i18n_application
SET key_set_revision = key_set_revision + 1, content_revision = content_revision + 1, update_time = #{now}
WHERE application_id = #{applicationId} AND key_set_revision = #{keySetRevision}

UPDATE t_i18n_application
SET content_revision = content_revision + 1, update_time = #{now}
WHERE application_id = #{applicationId} AND content_revision = #{contentRevision}

UPDATE t_i18n_application
SET current_release_id = #{releaseId}, update_time = #{now}
WHERE application_id = #{applicationId}

    AND current_release_id IS NULL
    AND current_release_id = #{expectedReleaseId}
